-- ════════════════════════════════════════════════════════════════
-- تطبيق القادة: القياس المبدئي baseline-v4 والبعدي post-v2
-- ════════════════════════════════════════════════════════════════
-- آمن لإعادة التشغيل. يُنشئ الأداتين غير مفعّلتين، ولا يمس v3 ولا post-v1
-- ولا نتائجهما. من بدأ على v3 يبقى عليه حتى قياسه البعدي (post-v1).
--
-- المراجعة الثانية للأسئلة (25 أكتوبر 2026):
--   1. صيغتان متوازيتان A وB بتوزيع متقاطع: نصف الدفعة A قبلًا وB بعدًا،
--      والنصف الآخر العكس، فيُلغى فرق صعوبة الصيغتين في متوسط الدفعة
--      ويُقدَّر لتصحيحه للفرد (Kolen و Brennan). العمود form: null مشترك.
--   2. لكل إطار 3 مواقف ربط مشتركة و3 موازية في كل صيغة، فيظهر أثر
--      تكرار الأسئلة بالمقارنة بين المشترك والموازي ويُطرح من التغير.
--   3. لا يلتقي موقف وسؤال معرفة على السيناريو نفسه (استُبدلت خمسة).
--   4. مشتتات معقولة: قاعدة «استبعد المتطرف» لم تعد ترفع الدرجة فوق التخمين.
--   5. عبارات ممارسة سلوكية يراها المدير، ومقياس تكرار بمراسٍ بالنسبة،
--      ونافذة زمنية واحدة: الأشهر الثلاثة الأخيرة قبلًا وبعدًا.
--   6. المدير يقدّر مرتين: مع القياس المبدئي ومع البعدي (raters.phase).

-- 1) الأعمدة
alter table leaders.questions   add column if not exists form text check (form in ('A', 'B'));
alter table leaders.assessments add column if not exists form text check (form in ('A', 'B'));
alter table leaders.instruments add column if not exists pairs_with text;   -- مفتاح القياس المبدئي الذي تقابله الأداة البعدية

alter table leaders.assessment_results add column if not exists skill_anchor_pct        numeric(5,2);  -- المواقف المشتركة بين الصيغتين
alter table leaders.assessment_results add column if not exists skill_form_pct          numeric(5,2);  -- المواقف الخاصة بصيغة المشارك
alter table leaders.assessment_results add column if not exists behavior_common_pct     numeric(5,2);  -- الممارسة على العبارات المجابة في القياسين
alter table leaders.assessment_results add column if not exists behavior_pre_common_pct numeric(5,2);

alter table leaders.placement_model add column if not exists min_behavior_items smallint not null default 3
  check (min_behavior_items between 0 and 10);
alter table leaders.placement_model add column if not exists rci_practice numeric(5,2) not null default 0
  check (rci_practice >= 0 and rci_practice <= 30);
-- عتبة المدير 10 كانت تساوي عبارتين تحركتا درجة واحدة، والعينة 20 تعطي ثباتًا بهامش واسع
update leaders.placement_model set rater_threshold = 15 where id = 1 and rater_threshold = 10;
update leaders.placement_model set impact_min_n = 50 where id = 1 and impact_min_n = 20;

-- 2) المدير مرتين: قبل البرنامج (تقدير الآن فقط) وبعده
alter table leaders.raters add column if not exists phase text not null default 'post' check (phase in ('pre', 'post'));
alter table leaders.raters drop constraint if exists raters_participant_id_email_key;
do $$ begin
  if not exists (select 1 from pg_constraint where conname = 'raters_participant_email_phase_key') then
    alter table leaders.raters add constraint raters_participant_email_phase_key unique (participant_id, email, phase);
  end if;
end $$;

-- 3) الأداتان
insert into leaders.instruments (key, title_ar, kind, active, version, intro_ar, est_minutes)
values ('baseline-v4', 'القياس المبدئي لإدارة المشروعات للقادة', 'baseline', false, 4,
  'يقيس هذا القياس ثلاثة جوانب في كل إطار: ممارستك الفعلية، وحكمك في مواقف العمل، ومعرفتك بالمفاهيم. عبارات الممارسة ليس فيها إجابة صحيحة، فأجب عما فعلته في الأشهر الثلاثة الأخيرة لا عما ينبغي فعله، ونتيجتك لا تُشارك مع جهتك. وفي المواقف اختر ما تراه الأنسب ولو لم يكن ما تفعله عادة.',
  18)
on conflict (key) do nothing;

insert into leaders.instruments (key, title_ar, kind, active, version, intro_ar, est_minutes, pairs_with)
values ('post-v2', 'القياس البعدي لبرنامج القادة', 'post', false, 2,
  'وصلت إلى نهاية الرحلة. هذا القياس يبيّن ما تغيّر فعلًا في ممارستك وحكمك، لا ما حفظته، وأسئلته غير أسئلة قياسك الأول في أغلبها. في عبارات الممارسة تقديران: الأشهر الثلاثة الأخيرة، والأشهر الثلاثة التي سبقت البرنامج كما تراها اليوم. ونتيجتك لا تُشارك مع جهتك إلا مجمّعة مع غيرك.',
  25, 'baseline-v4')
on conflict (key) do nothing;
-- post-v1 يقابل baseline-v3، فمن بدأ عليه لا يُحال إلى post-v2
update leaders.instruments set pairs_with = 'baseline-v3' where key = 'post-v1' and pairs_with is null;

-- 4) بنك baseline-v4: المشترك (form null) والصيغتان A وB.
-- صف لكل سؤال: الإطار، الرمز، الجانب، الصيغة، الترتيب، النص، البدائل (null للممارسة)،
-- الجدارة، الباب، صيغة الغائب للمدير.
insert into leaders.questions (instrument_id, dimension, code, tier, text_ar, help_ar, kind, options, sort,
  competency_ar, chapter_key, form, text_rater_ar)
select i.id, v.dimension, v.code, v.tier, v.text_ar,
  case when v.tier = 'behavior' then 'فكّر في الأشهر الثلاثة الأخيرة من عملك. اختر «لا ينطبق على عملي» إن لم تمرّ بهذا الموقف.' end,
  case when v.tier = 'behavior' then 'likert' else 'choice' end,
  coalesce(v.options, '[{"label": "نادرًا أو أبدًا", "score": 0}, {"label": "في أقل من نصف المرات", "score": 1}, {"label": "في نحو نصف المرات", "score": 2}, {"label": "في أغلب المرات", "score": 3}, {"label": "في كل المرات تقريبًا", "score": 4}, {"label": "لا ينطبق على عملي", "score": -1}]')::jsonb,
  v.sort, v.competency_ar, v.chapter_key, v.form, v.text_rater_ar
from leaders.instruments i
cross join (values
  ('milestone', 'M-B1', 'behavior', null, 1, 'أختم اجتماعات المتابعة التي أقودها بقرار موثق له مسؤول وموعد.', null, 'قيادة اجتماعات القرار', 'ch3', 'يختم اجتماعات المتابعة التي يقودها بقرار موثق له مسؤول وموعد.'),
  ('milestone', 'M-B2', 'behavior', null, 2, 'أتفق مع الجهة المستلمة على معايير قبول المخرج قبل تسليمه.', null, 'معايير التسليم والقبول', 'ch4', 'يتفق مع الجهة المستلمة على معايير قبول المخرج قبل تسليمه.'),
  ('milestone', 'M-B3', 'behavior', null, 3, 'في كل بوابة مرحلة، أراجع هل ما زال مبرر المشروع قائمًا.', null, 'مراجعة مبرر الاستمرار', 'ch3', 'في كل بوابة مرحلة، يراجع هل ما زال مبرر المشروع قائمًا.'),
  ('milestone', 'M-B4', 'behavior', null, 4, 'أقترح إيقاف عمل اتضح أنه لم يعد يخدم الهدف.', null, 'إيقاف ما لا يخدم القيمة', 'ch3', 'يقترح إيقاف عمل اتضح أنه لم يعد يخدم الهدف.'),
  ('milestone', 'M-S1', 'skill', null, 5, 'طُلب منك بناء سجل معالم لمشروع جديد. أي سجل هو الأفضل؟', '[{"label":"معالم لاكتمال كل مخرج، لكل منها تاريخ ومسؤول","score":1},{"label":"معالم قرارات ونتائج، لكل منها دليل يثبت بلوغها","score":4},{"label":"معلم في نهاية كل شهر لضمان انتظام التقارير","score":0},{"label":"معالم دفعات العقد مع المورد ومواعيد استحقاق كل دفعة","score":1}]', 'بناء سجل المعالم', 'ch4', null),
  ('milestone', 'M-S3', 'skill', null, 6, 'في تقارير المتابعة، يتأخر تاريخ معلم رئيسي أسبوعًا في كل تقرير منذ أربعة أشهر. ما أول خطوة؟', '[{"label":"مطالبة الفريق بخطة تسريع لتعويض الأسابيع المتأخرة","score":1},{"label":"تحليل السبب الجذري للانزلاق قبل أي تعديل للخطة","score":4},{"label":"اعتماد التاريخ الجديد في خط الأساس وإبلاغ الراعي","score":1},{"label":"الاستمرار في المتابعة لأن تأخير كل تقرير محدود","score":0}]', 'قراءة الانزلاق', 'ch4', null),
  ('milestone', 'M-S4', 'skill', null, 7, 'مشروع تنموي ممول من جهة مانحة، وتقارير المنحة ترهق الفريق ولا تُستخدم داخليًا. ما المعالجة الأنسب؟', '[{"label":"التفاوض مع المانح على تقرير فصلي بدل الشهري","score":1},{"label":"ربط مواعيد التقارير بمعالم القرار الداخلية","score":4},{"label":"إسناد التقارير لموظف متخصص بعيدًا عن الفريق","score":1},{"label":"دمج التقارير في تقرير سنوي واحد شامل","score":0}]', 'مواءمة متطلبات المانح', 'ch2', null),
  ('milestone', 'M-S2', 'skill', 'A', 8, 'في جلسة بوابة مرحلة: المشروع متأخر ثلاثة أسابيع، ومبرر الاستمرار قائم، والمخاطر معروفة. ما القرار الأنسب؟', '[{"label":"عبور مع تكليف المدير بعرض خطة تصحيح في الاجتماع الدوري القادم","score":2},{"label":"عبور مشروط بخطة تصحيح ومعلم مراجعة قريب","score":4},{"label":"إعادة عقد الجلسة بعد أسبوعين وقد حُدّث الجدول","score":1},{"label":"عبور مع طلب اعتماد خط أساس معدل بالتاريخ الجديد","score":1}]', 'قرار البوابة', 'ch3', null),
  ('milestone', 'M-S5', 'skill', 'A', 9, 'في منتصف مرحلة التنفيذ طلب الراعي إضافة خدمة يراها مهمة، ويقدّر الفريق أنها تضيف شهرًا. ما التصرف الأنسب؟', '[{"label":"إضافتها وإعادة توزيع الفريق لامتصاص الشهر الإضافي","score":0},{"label":"اقتراح إدراجها في إصدار لاحق بعد التسليم الأول","score":2},{"label":"عرض أثرها على الموعد والتكلفة مع بديلين ليقرر الراعي","score":4},{"label":"إضافتها مقابل حذف ميزة أقل أولوية باتفاق الفريق","score":1}]', 'ضبط تغيير النطاق', 'ch3', null),
  ('milestone', 'M-S6', 'skill', 'A', 10, 'أبلغك المورد أن تسليم مكون رئيسي سيتأخر ستة أسابيع، وهذا الخطر مسجل مسبقًا مع خطة استجابة. ما أول خطوة؟', '[{"label":"تفعيل خطة الاستجابة المسجلة وإبلاغ أصحاب القرار","score":4},{"label":"مطالبة المورد بخطة تعافٍ مكتوبة قبل تحديث الجدول","score":2},{"label":"تحديث الجدول بالتاريخ الجديد وإبلاغ أصحاب القرار في التقرير الشهري","score":1},{"label":"مطالبة المورد بغرامة التأخير المنصوص عليها في العقد","score":1}]', 'الاستجابة للمخاطر', 'ch3', null),
  ('milestone', 'M-S2B', 'skill', 'B', 8, 'في مراجعة مرحلية: المشروع ضمن الموعد، لكن دراسة حديثة تظهر أن الطلب على الخدمة أقل بكثير مما بُني عليه المبرر. ما القرار الأنسب؟', '[{"label":"الاستمرار مع تحديث دراسة الطلب خلال المرحلة القادمة","score":2},{"label":"الاستمرار لأن الأداء ضمن الخطة والميزانية المعتمدتين","score":1},{"label":"عرض المبرر المحدث على اللجنة لتقرر الاستمرار أو التعديل","score":4},{"label":"تسريع التنفيذ لإطلاق الخدمة قبل أن يتراجع الطلب أكثر","score":0}]', 'قرار البوابة', 'ch3', null),
  ('milestone', 'M-S5B', 'skill', 'B', 9, 'بعد اعتماد خطة مشروع لتطوير نظام داخلي، طلبت إدارة مستفيدة ربطه بنظام آخر لم يكن في النطاق. ما التصرف الأنسب؟', '[{"label":"تقديم طلب تغيير يبيّن أثر الربط على الوقت والتكلفة","score":4},{"label":"تسجيل الطلب ودراسته ضمن المرحلة الثانية من المشروع","score":2},{"label":"تنفيذ الربط إن قدّر الفريق أنه لا يؤخر موعد التسليم","score":1},{"label":"الاتفاق مع الإدارة المستفيدة مباشرة على تنفيذه","score":0}]', 'ضبط تغيير النطاق', 'ch3', null),
  ('milestone', 'M-S6B', 'skill', 'B', 10, 'قبل إطلاق خدمة بأسبوع تحقق خطر مسجل: انتقل الفريق التقني الرئيسي إلى مشروع آخر، وخطة الاستجابة تنص على فريق مساند. ما أول خطوة؟', '[{"label":"طلب إعادة الفريق الرئيسي من مدير المشروع الآخر","score":2},{"label":"تأجيل الإطلاق أسبوعين لتهيئة فريق جديد من الداخل","score":1},{"label":"تفعيل الفريق المساند وإبلاغ أصحاب القرار","score":4},{"label":"تقييم قدرة الفريق المساند ثم إبلاغ أصحاب القرار لاحقًا","score":1}]', 'الاستجابة للمخاطر', 'ch3', null),
  ('milestone', 'M-K2', 'knowledge', 'A', 11, 'أي النقاط التالية في مشروع إنشاء مركز خدمة تمثل بوابة مرحلة (Stage Gate)؟', '[{"label":"اجتماع الفريق الأسبوعي لمراجعة المهام والمخاطر","score":0},{"label":"استلام الدفعة الأولى من مواد البناء من المورد","score":0},{"label":"اعتماد اللجنة للتصميم قبل صرف ميزانية الإنشاء","score":4},{"label":"رفع تقرير الإنجاز الشهري إلى الإدارة العليا","score":0}]', 'البوابة والمعلم', 'ch3', null),
  ('milestone', 'M-K4', 'knowledge', 'A', 12, 'جهة تطلق برنامجًا متطلباته واضحة ومستقرة، وتشترط اعتماد اللجنة قبل كل مرحلة وصرف الميزانية على دفعات. أي نهج أنسب لإدارته؟', '[{"label":"نهج تنبؤي بمراحل وبوابات اعتماد","score":4},{"label":"نهج تكيفي بدورات قصيرة وأولويات متغيرة","score":0},{"label":"نهج هجين يبدأ تكيفيًا ثم يصبح تنبؤيًا","score":0},{"label":"إدارة تشغيلية بمؤشرات أداء شهرية","score":0}]', 'اختيار نهج الإدارة', 'ch1', null),
  ('milestone', 'M-K5', 'knowledge', 'A', 13, 'في الجدول الزمني، ماذا يعني أن نشاطًا يقع على المسار الحرج؟', '[{"label":"أن تأخيره يؤخر موعد انتهاء المشروع مباشرة","score":4},{"label":"أنه أعلى الأنشطة تكلفة في ميزانية المشروع","score":0},{"label":"أنه يحتاج أكبر عدد من أعضاء الفريق","score":0},{"label":"أنه يحمل أعلى درجة مخاطر في سجل المخاطر","score":0}]', 'المسار الحرج', 'ch4', null),
  ('milestone', 'M-K6', 'knowledge', 'A', 14, 'ما الغرض الأساسي من إجراء ضبط التغيير في المشروع؟', '[{"label":"منع أي تعديل على النطاق بعد اعتماده","score":0},{"label":"تقييم أثر كل تغيير قبل اعتماده أو رفضه","score":4},{"label":"توثيق التغييرات بعد تنفيذها لأغراض التدقيق","score":0},{"label":"إحالة طلبات التغيير إلى الراعي ليقررها وحده","score":0}]', 'ضبط التغيير', 'ch4', null),
  ('milestone', 'M-K7', 'knowledge', 'A', 15, 'ما الفرق بين الخطر (Risk) والمشكلة (Issue)؟', '[{"label":"الخطر حدث محتمل لم يقع، والمشكلة حدث وقع فعلًا","score":4},{"label":"الخطر يخص التكلفة، والمشكلة تخص الجدول الزمني","score":0},{"label":"الخطر يديره الراعي، والمشكلة يديرها المدير","score":0},{"label":"الخطر مصدره خارجي، والمشكلة مصدرها داخل الفريق","score":0}]', 'الخطر والمشكلة', 'ch4', null),
  ('milestone', 'M-K8', 'knowledge', 'A', 16, 'ما خط الأساس (Baseline) في إدارة المشروعات؟', '[{"label":"النسخة المعتمدة من الخطة للقياس عليها","score":4},{"label":"أحدث نسخة من الخطة بعد آخر تحديث أجراه فريق المشروع","score":0},{"label":"الحد الأدنى من النطاق المقبول لتسليم المشروع","score":0},{"label":"تقدير أولي للتكلفة قبل دراسة الجدوى التفصيلية","score":0}]', 'خط الأساس', 'ch4', null),
  ('milestone', 'M-K2B', 'knowledge', 'B', 11, 'أي عبارة تصف بوابة المرحلة (Stage Gate) وصفًا صحيحًا؟', '[{"label":"أي موعد تسليم يرد في الجدول الزمني المعتمد للمشروع مع مسؤوله","score":0},{"label":"اجتماع أسبوعي ثابت يتابع فيه الفريق تقدم المهام والمخاطر","score":0},{"label":"تقرير ختامي يُرفع إلى اللجنة بعد إغلاق المشروع وتسليم مخرجاته","score":0},{"label":"معلم يُتخذ عنده قرار رسمي بالاستمرار أو التعديل أو الإيقاف","score":4}]', 'البوابة والمعلم', 'ch3', null),
  ('milestone', 'M-K4B', 'knowledge', 'B', 12, 'فريق يبني خدمة رقمية جديدة، ومتطلباتها غير واضحة وتتغير مع ملاحظات المستخدمين كل أسبوعين. أي نهج أنسب؟', '[{"label":"نهج تنبؤي بخطة تفصيلية معتمدة من البداية حتى الإغلاق","score":0},{"label":"نهج تكيفي بدورات قصيرة وتخطيط يتجدد مع المستخدمين","score":4},{"label":"تجميد المتطلبات حتى تتضح ثم البدء في التنفيذ","score":0},{"label":"إدارة تشغيلية بمؤشرات أداء شهرية لكل فريق","score":0}]', 'اختيار نهج الإدارة', 'ch1', null),
  ('milestone', 'M-K5B', 'knowledge', 'B', 13, 'نشاط ليس على المسار الحرج وله فائض زمني (Float) قدره خمسة أيام. ماذا يحدث إن تأخر ثلاثة أيام؟', '[{"label":"يتأخر انتهاء المشروع ثلاثة أيام","score":0},{"label":"يطول المسار الحرج خمسة أيام","score":0},{"label":"لا يتأثر موعد انتهاء المشروع","score":4},{"label":"يلزم اعتماد خط أساس جديد","score":0}]', 'المسار الحرج', 'ch4', null),
  ('milestone', 'M-K6B', 'knowledge', 'B', 14, 'ما الذي يميّز طلب التغيير الرسمي عن التعديل اليومي في المهام؟', '[{"label":"أنه يأتي من الراعي أو من الإدارة العليا للجهة","score":0},{"label":"أنه يمس نطاقًا أو موعدًا أو تكلفة معتمدة","score":4},{"label":"أنه يتطلب إضافة أعضاء جدد إلى فريق المشروع","score":0},{"label":"أنه يُوثَّق بالبريد الإلكتروني لا في الاجتماع","score":0}]', 'ضبط التغيير', 'ch4', null),
