  ('leadership', 'L-S6', 'skill', null, 47, 'اتضح لك أن البرنامج لن يحقق مستهدفه السنوي، ومراجعة الأداء مع المسؤول الأعلى بعد أسبوع. ما الأنسب؟', '[{"label":"إبلاغه الآن بالأسباب وخيارات المعالجة","score":4},{"label":"عرض الأمر في المراجعة كما هو مجدول","score":1},{"label":"عرضه في المراجعة مع خطة تعويض جاهزة","score":2},{"label":"إبراز المؤشرات المتحققة وترك المتأخر للربع القادم","score":0}]', 'إيصال الأخبار الصعبة', 'ch2', null),
  ('leadership', 'L-S1', 'skill', 'A', 48, 'كلّفت عضوًا انضم حديثًا بإعداد أول خطة تواصل في مسيرته، وهو يبادر ويطلب مزيدًا من المهام. ما الأسلوب الأنسب معه في هذه المهمة؟', '[{"label":"تفويض المهمة مع موعد تسليم واضح","score":0},{"label":"تعليمات محددة ومتابعة قريبة","score":4},{"label":"تشجيعه ودعمه وترك طريقة التنفيذ له","score":1},{"label":"شرح المطلوب ثم مراجعة النسخة النهائية معه","score":1}]', 'توجيه عضو جديد', 'ch4', null),
  ('leadership', 'L-S2', 'skill', 'A', 49, 'خلاف مع إدارة موازية على مورد مشترك. القضية مهمة لمشروعك، والعلاقة ممتدة، وأمامكما أسبوعان قبل الحاجة إلى المورد. ما الأنسب؟', '[{"label":"حسم المورد لصالح مشروعك عبر الإدارة العليا","score":1},{"label":"جلسة مشتركة لبناء حل يلبي حاجة الطرفين","score":4},{"label":"تقاسم المورد مناصفة لإنهاء الخلاف سريعًا","score":1},{"label":"اقتراح جدول تناوب على المورد يعتمده المديران","score":2}]', 'إدارة الخلاف', 'ch6', null),
  ('leadership', 'L-S5', 'skill', 'A', 50, 'ستنتقل إلى مهمة جديدة بعد أسبوعين، وسيتسلم زميلك مشروعك. ما الأنسب؟', '[{"label":"تسليمه الملفات كاملة مع محضر رسمي موقّع","score":1},{"label":"مرافقته في الاجتماعات والقرارات حتى يقودها بنفسه","score":4},{"label":"إعداد تقرير مفصل عن حالة المشروع وإرساله إليه","score":1},{"label":"إبقاء قنوات التواصل مفتوحة لأي سؤال يطرأ لاحقًا","score":1}]', 'التسليم والتسلم', 'ch3', null),
  ('leadership', 'L-S1B', 'skill', 'B', 48, 'انضم إليك موظف من إدارة أخرى، خبرته طويلة في المشتريات لكنه يدير مشروعًا لأول مرة ويتردد في اتخاذ القرارات. ما الأسلوب الأنسب معه في أول مهمة؟', '[{"label":"تفويضه المهمة كاملة اعتمادًا على خبرته الطويلة","score":1},{"label":"تشجيعه وترك طريقة التنفيذ له ليبني ثقته","score":1},{"label":"خطوات واضحة ومتابعة قريبة مع شرح سبب كل خطوة","score":4},{"label":"إسناد المهمة لزميل أقدم ليتعلم منه بالمشاهدة","score":0}]', 'توجيه عضو جديد', 'ch4', null),
  ('leadership', 'L-S2B', 'skill', 'B', 49, 'إدارتك وإدارة أخرى تحتاجان قاعة التدريب الوحيدة في الأسبوع نفسه، ولكل منهما برنامج معتمد، والعلاقة بينكما جيدة. ما الأنسب؟', '[{"label":"لقاء مع مدير الإدارة الأخرى لبحث بدائل تلبي البرنامجين","score":4},{"label":"اقتراح تقسيم أيام الأسبوع بين البرنامجين","score":2},{"label":"رفع الأمر لمن يملك صلاحية تخصيص القاعة ليحسمه","score":1},{"label":"نقل برنامجك إلى موعد لاحق حفاظًا على العلاقة","score":0}]', 'إدارة الخلاف', 'ch6', null),
  ('leadership', 'L-S5B', 'skill', 'B', 50, 'سيتسلم زميل منك ملف شراكة مع جهة خارجية بعد ثلاثة أسابيع، والعلاقة مع ممثل الجهة قائمة على ثقة بنيتها معه. ما الأنسب؟', '[{"label":"إرسال ملخص مكتوب عن الشراكة وحالتها إليه","score":1},{"label":"تسليمه الملف ووثائق الاتفاقية بمحضر رسمي","score":1},{"label":"إبلاغ ممثل الجهة بالتغيير في رسالة رسمية","score":1},{"label":"تعريفه بممثل الجهة وحضوره معك اللقاءات حتى يتولاها","score":4}]', 'التسليم والتسلم', 'ch3', null),
  ('leadership', 'L-K2', 'knowledge', 'A', 51, 'في القيادة الموقفية، على أي أساس يُختار أسلوب القائد مع الفرد؟', '[{"label":"شخصية القائد وما اعتاد عليه","score":0},{"label":"قدرة الفرد ورغبته في المهمة المحددة","score":4},{"label":"أقدمية الفرد ومستواه الوظيفي","score":0},{"label":"حجم المشروع وحساسية مخرجاته للجهة المالكة","score":0}]', 'القيادة الموقفية', 'ch4', null),
  ('leadership', 'L-K5', 'knowledge', 'A', 52, 'مدير مشروع يحتاج تعاون إدارة لا سلطة له عليها. ما الأساس الأقوى للتأثير فيها؟', '[{"label":"رفع الأمر إلى الإدارة العليا لإلزامها بالتعاون","score":0},{"label":"ربط طلبه بمصلحة تهم تلك الإدارة نفسها","score":4},{"label":"الاستناد إلى أقدميته وخبرته الطويلة في الجهة","score":0},{"label":"تكرار الطلب رسميًا حتى تستجيب الإدارة","score":0}]', 'التأثير دون سلطة', 'ch6', null),
  ('leadership', 'L-K6', 'knowledge', 'A', 53, 'ما المقصود بالأمان النفسي في الفريق؟', '[{"label":"ثقة الأعضاء بأن الاعتراض والخطأ لا يجلبان العقاب","score":4},{"label":"ضمان استقرار وظائف الأعضاء حتى نهاية المشروع","score":0},{"label":"تجنب الخلافات داخل الفريق حفاظًا على الانسجام","score":0},{"label":"حماية الفريق من ضغط الإدارة العليا ومطالبها المتكررة","score":0}]', 'الأمان النفسي', 'ch6', null),
  ('leadership', 'L-K7', 'knowledge', 'A', 54, 'في مصفوفة المسؤوليات (RACI)، من يمثله الحرف A؟', '[{"label":"من ينفذ العمل بنفسه","score":0},{"label":"من يُستشار قبل التنفيذ","score":0},{"label":"من يُحاسب على النتيجة","score":4},{"label":"من يُبلَّغ بعد اتخاذ القرار","score":0}]', 'المساءلة', 'ch4', null),
  ('leadership', 'L-K8', 'knowledge', 'A', 55, 'وفق نموذج كوتر لقيادة التغيير، ما الخطوة الأولى؟', '[{"label":"صياغة رؤية التغيير ونشرها","score":0},{"label":"بناء الإحساس بضرورة التغيير","score":4},{"label":"تحقيق مكاسب سريعة ظاهرة","score":0},{"label":"تشكيل تحالف قيادي داعم","score":0}]', 'قيادة التغيير', 'ch6', null),
  ('leadership', 'L-K9', 'knowledge', 'A', 56, 'أي صياغة للملاحظة على أداء زميل هي الأكثر فاعلية؟', '[{"label":"أنت لا تهتم بمواعيد التسليم كما ينبغي","score":0},{"label":"تأخر تقريرك يومين فتأخر قرار اللجنة","score":4},{"label":"أرجو أن تكون أكثر التزامًا في الفترة القادمة","score":0},{"label":"الفريق كله لاحظ أن أداءك تراجع في الفترة الأخيرة","score":0}]', 'الملاحظة البنّاءة', 'ch4', null),
  ('leadership', 'L-K2B', 'knowledge', 'B', 51, 'موظف خبير في مهمته لكنه فقد حماسه لها مؤخرًا. أي أسلوب أنسب معه وفق القيادة الموقفية؟', '[{"label":"تعليمات تفصيلية ومتابعة قريبة لكل خطوة","score":0},{"label":"الدعم وإشراكه في القرار مع توجيه قليل","score":4},{"label":"تفويض كامل مع مراجعة في نهاية المهمة","score":0},{"label":"نقله إلى مهمة جديدة يتعلمها من البداية","score":0}]', 'القيادة الموقفية', 'ch4', null),
  ('leadership', 'L-K5B', 'knowledge', 'B', 52, 'أي ما يلي من مصادر التأثير لا يعتمد على السلطة الرسمية؟', '[{"label":"صلاحية اعتماد الميزانية وصرفها","score":0},{"label":"حق التقييم السنوي لأداء الموظف","score":0},{"label":"الخبرة والثقة والعلاقات المتبادلة","score":4},{"label":"قرار التعيين والنقل والترقية في الإدارة","score":0}]', 'التأثير دون سلطة', 'ch6', null),
  ('leadership', 'L-K6B', 'knowledge', 'B', 53, 'أي سلوك من القائد يبني الأمان النفسي في الفريق أكثر من غيره؟', '[{"label":"أن يعترف بأخطائه ويشكر من ينبّه إلى خلل","score":4},{"label":"أن يتجنب الخلاف داخل الفريق حفاظًا على الانسجام","score":0},{"label":"أن يعد الفريق بعدم تغيير المهام حتى نهاية المشروع","score":0},{"label":"أن يحمي الفريق من أي ملاحظة تأتي من خارجه","score":0}]', 'الأمان النفسي', 'ch6', null),
  ('leadership', 'L-K7B', 'knowledge', 'B', 54, 'في مصفوفة RACI، كم شخصًا يُفضّل أن يكون في خانة A لكل مهمة؟', '[{"label":"اثنان: المنفذ ومديره المباشر","score":0},{"label":"بعدد المنفذين للمهمة نفسها","score":0},{"label":"بحسب حجم المهمة وأهميتها","score":0},{"label":"شخص واحد","score":4}]', 'المساءلة', 'ch4', null),
  ('leadership', 'L-K8B', 'knowledge', 'B', 55, 'وفق نموذج كوتر، لماذا يُنصح بتحقيق مكاسب سريعة قصيرة المدى؟', '[{"label":"لإعلان انتهاء التغيير مبكرًا","score":0},{"label":"لإثبات جدوى التغيير للمتشككين والحفاظ على زخمه","score":4},{"label":"لتقليل الحاجة إلى بناء تحالف قيادي داعم","score":0},{"label":"للاستغناء عن صياغة رؤية التغيير ونشرها","score":0}]', 'قيادة التغيير', 'ch6', null),
  ('leadership', 'L-K9B', 'knowledge', 'B', 56, 'ما الذي يجعل الملاحظة على الأداء بنّاءة؟', '[{"label":"أن تكون عامة حتى لا تجرح الشخص المعني","score":0},{"label":"أن تصف سلوكًا محددًا وأثره، ثم تفتح حوارًا عن الحل","score":4},{"label":"أن تُقال أمام الفريق كله ليتعلم الجميع منها","score":0},{"label":"أن تُؤجل إلى التقييم السنوي لتكون شاملة","score":0}]', 'الملاحظة البنّاءة', 'ch4', null)
) as v(dimension, code, tier, form, sort, text_ar, options, competency_ar, chapter_key, text_rater_ar)
where i.key = 'baseline-v4'
on conflict (instrument_id, code) do nothing;

-- 5) post-v2: البنك نفسه كاملًا (المعرفة أيضًا)، وكل سؤال يربطه رمزه بنظيره.
-- المشارك يأخذ في البعدي الصيغة الأخرى غير صيغته في المبدئي، فلا يتكرر عليه
-- إلا المشترك. عبارات الممارسة بتقديرين: الآن وقبل البرنامج.
insert into leaders.questions (instrument_id, dimension, code, tier, text_ar, help_ar, kind, options, weight, sort,
  competency_ar, chapter_key, form, text_rater_ar, anchor_code, retro)
select post.id, q.dimension, q.code, q.tier, q.text_ar,
  case when q.tier = 'behavior'
    then 'قدّر ممارستك في الأشهر الثلاثة الأخيرة، ثم في الأشهر الثلاثة التي سبقت البرنامج. اختر «لا ينطبق على عملي» إن لم تمرّ بهذا الموقف.'
    else q.help_ar end,
  q.kind, q.options, q.weight, q.sort, q.competency_ar, q.chapter_key, q.form, q.text_rater_ar, q.code, q.tier = 'behavior'
from leaders.questions q
join leaders.instruments base on base.id = q.instrument_id and base.key = 'baseline-v4'
cross join (select id from leaders.instruments where key = 'post-v2') post
where q.active
on conflict (instrument_id, code) do nothing;

-- انتقال التعلم: كما في post-v1، لا يدخل في الدرجة
insert into leaders.questions (instrument_id, dimension, code, tier, text_ar, help_ar, kind, options, sort)
select post.id, 'leadership', v.code, 'transfer', v.t, 'عن تجربتك في البرنامج وبيئة عملك، لا عن أدائك.', 'likert',
  '[{"label": "لا أوافق بشدة", "score": 0}, {"label": "لا أوافق", "score": 1}, {"label": "محايد", "score": 2}, {"label": "أوافق", "score": 3}, {"label": "أوافق بشدة", "score": 4}]'::jsonb, v.s
from (values
  ('T-1', 'ما تعلمته في البرنامج يرتبط مباشرة بتحديات عملي الفعلية.', 101),
  ('T-2', 'أتيحت لي فرص حقيقية لتطبيق ما تعلمته خلال البرنامج.', 102),
  ('T-3', 'دعمني مديري المباشر في تطبيق ما تعلمته.', 103),
  ('T-4', 'أستطيع أن أذكر قرارًا محددًا اتخذته بطريقة مختلفة بسبب البرنامج.', 104),
  ('T-5', 'سأستمر في استخدام أدوات البرنامج بعد انتهائه.', 105)
) as v(code, t, s)
cross join (select id from leaders.instruments where key = 'post-v2') post
on conflict (instrument_id, code) do nothing;

notify pgrst, 'reload schema';
